// Reference to generated workflow functions
var (
	// terraformRegistrationMutex is a mutex for registering terraform.v1.Terraform workflows
	terraformRegistrationMutex sync.Mutex
	// ApplyTerraform applies a pre-generated Terraform plan to the cluster
	// Used with PlanTerraform for two-step deployments (plan first, review, then apply)
	ApplyTerraformFunction func(workflow.Context, *ApplyTerraformInput) (*ApplyTerraformOutput, error)
	// CreateTerraform initializes fresh Terraform state and applies configuration
	// Used when deploying a module for the first time (no prior state)
	CreateTerraformFunction func(workflow.Context, *CreateTerraformInput) (*CreateTerraformOutput, error)
	// DestroyTerraform destroys infrastructure managed by Terraform
	// Writes tombstone marker to S3 on successful destruction
	DestroyTerraformFunction func(workflow.Context, *DestroyTerraformInput) (*DestroyTerraformOutput, error)
	// PlanTerraform generates a Terraform plan (dry-run, shows what would change)
	// Produces a plan artifact that can be reviewed or applied separately
	PlanTerraformFunction func(workflow.Context, *PlanTerraformInput) (*PlanTerraformOutput, error)
	// UpdateTerraform updates existing Terraform state with new configuration
	// Used when modifying an existing module deployment (state already exists in S3)
	UpdateTerraformFunction func(workflow.Context, *UpdateTerraformInput) (*UpdateTerraformOutput, error)
)

// TerraformWorkflowFunctions describes a mockable dependency for inlining workflows within other workflows
type (
	// TerraformWorkflowFunctions describes a mockable dependency for inlining workflows within other workflows
	TerraformWorkflowFunctions interface {
		// ApplyTerraform applies a pre-generated Terraform plan to the cluster
		// Used with PlanTerraform for two-step deployments (plan first, review, then apply)
		ApplyTerraform(workflow.Context, *ApplyTerraformInput) (*ApplyTerraformOutput, error)
		// CreateTerraform initializes fresh Terraform state and applies configuration
		// Used when deploying a module for the first time (no prior state)
		CreateTerraform(workflow.Context, *CreateTerraformInput) (*CreateTerraformOutput, error)
		// DestroyTerraform destroys infrastructure managed by Terraform
		// Writes tombstone marker to S3 on successful destruction
		DestroyTerraform(workflow.Context, *DestroyTerraformInput) (*DestroyTerraformOutput, error)
		// PlanTerraform generates a Terraform plan (dry-run, shows what would change)
		// Produces a plan artifact that can be reviewed or applied separately
		PlanTerraform(workflow.Context, *PlanTerraformInput) (*PlanTerraformOutput, error)
		// UpdateTerraform updates existing Terraform state with new configuration
		// Used when modifying an existing module deployment (state already exists in S3)
		UpdateTerraform(workflow.Context, *UpdateTerraformInput) (*UpdateTerraformOutput, error)
	}
	// terraformWorkflowFunctions provides an internal TerraformWorkflowFunctions implementation
	terraformWorkflowFunctions struct{}
)

func NewTerraformWorkflowFunctions() TerraformWorkflowFunctions {
	return &terraformWorkflowFunctions{}
}

// ApplyTerraform applies a pre-generated Terraform plan to the cluster
// Used with PlanTerraform for two-step deployments (plan first, review, then apply)
func (f *terraformWorkflowFunctions) ApplyTerraform(ctx workflow.Context, req *ApplyTerraformInput) (*ApplyTerraformOutput, error) {
	if ApplyTerraformFunction == nil {
		return nil, errors.New("ApplyTerraform requires workflow registration via RegisterTerraformWorkflows or RegisterApplyTerraformWorkflow")
	}
	return ApplyTerraformFunction(ctx, req)
}

// CreateTerraform initializes fresh Terraform state and applies configuration
// Used when deploying a module for the first time (no prior state)
