// TerraformActivities describes available worker activities
type TerraformActivities interface {
	// ApplyTerraform applies a pre-generated Terraform plan to the cluster
	// Used with PlanTerraform for two-step deployments (plan first, review, then apply)
	ApplyTerraform(ctx context.Context, req *ApplyTerraformInput) (*ApplyTerraformOutput, error)

	// CreateTerraform initializes fresh Terraform state and applies configuration
	// Used when deploying a module for the first time (no prior state)
	CreateTerraform(ctx context.Context, req *CreateTerraformInput) (*CreateTerraformOutput, error)

	// DestroyTerraform destroys infrastructure managed by Terraform
	// Writes tombstone marker to S3 on successful destruction
	DestroyTerraform(ctx context.Context, req *DestroyTerraformInput) (*DestroyTerraformOutput, error)

	// PlanTerraform generates a Terraform plan (dry-run, shows what would change)
	// Produces a plan artifact that can be reviewed or applied separately
	PlanTerraform(ctx context.Context, req *PlanTerraformInput) (*PlanTerraformOutput, error)

	// UpdateTerraform updates existing Terraform state with new configuration
	// Used when modifying an existing module deployment (state already exists in S3)
	UpdateTerraform(ctx context.Context, req *UpdateTerraformInput) (*UpdateTerraformOutput, error)
}

// RegisterTerraformActivities registers activities with a worker
func RegisterTerraformActivities(r worker.ActivityRegistry, activities TerraformActivities) {
	RegisterApplyTerraformActivity(r, activities.ApplyTerraform)
	RegisterCreateTerraformActivity(r, activities.CreateTerraform)
	RegisterDestroyTerraformActivity(r, activities.DestroyTerraform)
	RegisterPlanTerraformActivity(r, activities.PlanTerraform)
	RegisterUpdateTerraformActivity(r, activities.UpdateTerraform)
}

